206:         }
207:       }
208:       const hatStart = start + Math.floor(sampleRate * beat * 0.5);
209:       for (let i = 0; i < sampleRate * 0.045 && hatStart + i < length; i++) {
210:         const t = i / sampleRate;
211:         samples[hatStart + i] += (random() * 2 - 1) * Math.exp(-t * 75) * 0.08;
212:       }
213:     }
214:     const buffer = new ArrayBuffer(44 + samples.length * 2);
215:     const view = new DataView(buffer);
216:     const write = (offset, text) => [...text].forEach((char, index) => view.setUint8(offset + index, char.charCodeAt(0)));
217:     write(0, 'RIFF'); view.setUint32(4, 36 + samples.length * 2, true); write(8, 'WAVE');
