309:   async function analyzeOfflineBpm(id) {
310:     const deck = decks[id];
311:     const url = deck.objectUrl;
312:     if (!url || url.startsWith('https://') || !window.AudioContext && !window.webkitAudioContext) return;
313:     try {
314:       const response = await fetch(url);
315:       if (!response.ok) return;
316:       const audioBuffer = await response.arrayBuffer();
317:       if (deck.objectUrl !== url) return;
318:       const OfflineContext = window.OfflineAudioContext || window.webkitOfflineAudioContext;
319:       if (!OfflineContext) return;
320:       const context = new OfflineContext(1, 1, 11025);
321:       const decoded = await context.decodeAudioData(audioBuffer);
322:       const samples = decoded.getChannelData(0);
323:       const sampleRate = decoded.sampleRate;
324:       const hop = 256;
325:       const energies = [];
326:       for (let start = 0; start + 1024 < samples.length; start += hop) {
327:         let energy = 0;
328:         for (let i = 0; i < 1024; i++) energy += samples[start + i] ** 2;
329:         energies.push(Math.sqrt(energy / 1024));
330:       }
331:       if (deck.objectUrl !== url || energies.length < 20) return;
332:       const mean = energies.reduce((sum, value) => sum + value, 0) / energies.length;
333:       const peaks = [];
334:       for (let i = 1; i < energies.length - 1; i++) {
335:         if (energies[i] > mean * 1.45 && energies[i] >= energies[i - 1] && energies[i] > energies[i + 1] && i - (peaks.at(-1)?.index || -Infinity) > Math.floor(sampleRate * 0.22 / hop)) peaks.push({ index: i, time: i * hop / sampleRate });
336:       }
337:       const intervals = peaks.slice(1).map((peak, i) => peak.time - peaks[i].time).filter(value => value > 0.28 && value < 1.5).sort((a, b) => a - b);
338:       if (intervals.length < 3) return;
339:       let bpm = 60 / intervals[Math.floor(intervals.length / 2)];
340:       if (bpm < 70) bpm *= 2; else if (bpm > 160) bpm /= 2;
341:       if (bpm >= 70 && bpm <= 160) {
342:         deck.estimatedBpm = bpm;
343:         deck.baseBpm = bpm;
344:         setPitch(id, deck.pitch);
345:         $(`#analysis-status-${id}`).textContent = `LOCAL · ≈${bpm.toFixed(1)} BPM`;
