352:   function estimateBpmFromEnergy(id) {
353:     const deck = decks[id];
354:     const samples = deck.bpmSamples;
355:     if (samples.length < 36) return;
356:     const mean = samples.reduce((sum, sample) => sum + sample.energy, 0) / samples.length;
357:     const variance = samples.reduce((sum, sample) => sum + (sample.energy - mean) ** 2, 0) / samples.length;
358:     if (variance < 0.00002) return;
359:     const threshold = mean + Math.sqrt(variance) * 0.7;
360:     const peaks = [];
361:     for (let i = 1; i < samples.length - 1; i++) {
362:       if (samples[i].energy > threshold && samples[i].energy >= samples[i - 1].energy && samples[i].energy > samples[i + 1].energy && samples[i].time - (peaks.at(-1)?.time || -Infinity) > 0.22) peaks.push(samples[i]);
363:     }
364:     if (peaks.length < 5) return;
365:     const intervals = peaks.slice(1).map((peak, i) => peak.time - peaks[i].time).filter(interval => interval > 0.28 && interval < 1.5).sort((a, b) => a - b);
366:     if (intervals.length < 4) return;
367:     const interval = intervals[Math.floor(intervals.length / 2)];
368:     const bpm = 60 / interval;
369:     const normalized = bpm < 70 ? bpm * 2 : bpm > 160 ? bpm / 2 : bpm;
370:     if (normalized >= 70 && normalized <= 160) {
371:       deck.estimatedBpm = normalized;
372:       $(`#analysis-status-${id}`).textContent = `LOCAL · ≈${normalized.toFixed(1)} BPM`;
373:     }
374:   }
